-- Initial production schema. Apply through Supabase migrations; do not disable RLS.
create extension if not exists pgcrypto;
create type public.app_role as enum ('super_admin','admin','manager','coordinator','member');
create function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at = now(); return new; end $$;

create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null, mobile text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.user_roles(user_id uuid not null references auth.users(id) on delete cascade, role public.app_role not null, created_at timestamptz not null default now(), primary key(user_id,role));
create table public.permissions(id uuid primary key default gen_random_uuid(), key text not null unique, description text);
create table public.role_permissions(role public.app_role not null, permission_id uuid not null references public.permissions(id) on delete cascade, primary key(role,permission_id));
create function public.has_role(allowed public.app_role[]) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.user_roles where user_id=auth.uid() and role=any(allowed)) $$;
revoke all on function public.has_role(public.app_role[]) from public; grant execute on function public.has_role(public.app_role[]) to authenticated;

create table public.organization_settings(key text primary key, value jsonb not null default '{}'::jsonb, updated_by uuid references auth.users(id), updated_at timestamptz not null default now());
create table public.system_settings(key text primary key, value jsonb not null default '{}'::jsonb, updated_at timestamptz not null default now());
create table public.organizational_units(id uuid primary key default gen_random_uuid(), parent_id uuid references public.organizational_units(id), level smallint not null check(level between 1 and 11), name text not null, state text, district text, locality text, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.designations(id uuid primary key default gen_random_uuid(), name text not null unique, active boolean not null default true, sort_order int not null default 0);
create table public.members(id uuid primary key default gen_random_uuid(), user_id uuid unique references auth.users(id), unit_id uuid references public.organizational_units(id), designation_id uuid references public.designations(id), full_name text not null, mobile text not null, email text, state text, district text, membership_no text unique, category text, status text not null default 'pending' check(status in ('pending','approved','rejected','blocked','deactivated','expired')), date_of_birth date, photo_path text, public_photo boolean not null default false, valid_until date, approved_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index members_unit_idx on public.members(unit_id); create index members_status_idx on public.members(status); create index members_district_idx on public.members(district);
create table public.membership_applications(id uuid primary key default gen_random_uuid(), full_name text not null, mobile text not null, email text, state text, message text, status text not null default 'pending' check(status in ('pending','approved','rejected')), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, created_at timestamptz not null default now());
create table public.membership_categories(id uuid primary key default gen_random_uuid(), name text not null unique, fee_paise bigint not null default 0 check(fee_paise>=0), active boolean not null default true);
create table public.membership_payments(id uuid primary key default gen_random_uuid(), member_id uuid references public.members(id), transaction_ref text not null unique, amount_paise bigint not null check(amount_paise>0), gateway text, gateway_ref text unique, status text not null default 'pending' check(status in ('pending','success','failed','refunded','cancelled')), paid_at timestamptz, created_at timestamptz not null default now());
create table public.membership_renewals(id uuid primary key default gen_random_uuid(), member_id uuid not null references public.members(id), payment_id uuid references public.membership_payments(id), valid_until date not null, created_at timestamptz not null default now());
create table public.id_cards(id uuid primary key default gen_random_uuid(), member_id uuid not null unique references public.members(id), token_hash text not null unique, valid_until date, revoked_at timestamptz, created_at timestamptz not null default now());
create table public.id_verifications(id uuid primary key default gen_random_uuid(), id_card_id uuid references public.id_cards(id), viewed_at timestamptz not null default now());
create table public.appointment_letters(id uuid primary key default gen_random_uuid(), member_id uuid not null references public.members(id), letter_no text not null unique, unit_id uuid references public.organizational_units(id), designation_id uuid references public.designations(id), issued_at date not null, valid_until date, status text not null default 'issued' check(status in ('issued','renewed','cancelled','revoked')), token_hash text not null unique, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.appointment_verifications(id uuid primary key default gen_random_uuid(), letter_id uuid references public.appointment_letters(id), viewed_at timestamptz not null default now());
create table public.certificates(id uuid primary key default gen_random_uuid(), member_id uuid not null references public.members(id), certificate_no text not null unique, certificate_type text not null, title text not null, description text, issued_at date not null default current_date, status text not null default 'issued', token_hash text not null unique, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.certificate_verifications(id uuid primary key default gen_random_uuid(), certificate_id uuid references public.certificates(id), viewed_at timestamptz not null default now());
create table public.managers(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), unit_id uuid references public.organizational_units(id), created_at timestamptz not null default now());
create table public.coordinators(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id), unit_id uuid references public.organizational_units(id), created_at timestamptz not null default now());
create table public.referrals(id uuid primary key default gen_random_uuid(), referrer_member_id uuid not null references public.members(id), referred_member_id uuid references public.members(id), referral_code text not null unique, created_at timestamptz not null default now());
create table public.donations(id uuid primary key default gen_random_uuid(), donor_name text not null, donor_email text, amount_paise bigint not null check(amount_paise>0), purpose text, campaign_id uuid, transaction_ref text not null unique, gateway text, gateway_ref text unique, status text not null default 'pending' check(status in ('pending','success','failed','refunded','cancelled')), paid_at timestamptz, created_at timestamptz not null default now());
create table public.donation_receipts(id uuid primary key default gen_random_uuid(), donation_id uuid not null unique references public.donations(id), receipt_no text not null unique, generated_at timestamptz not null default now());
create table public.crowdfunding_campaigns(id uuid primary key default gen_random_uuid(), title text not null, description text, target_paise bigint not null check(target_paise>=0), status text not null default 'draft', start_date date, end_date date, created_at timestamptz not null default now());
alter table public.donations add constraint donations_campaign_fk foreign key(campaign_id) references public.crowdfunding_campaigns(id);
create table public.campaign_updates(id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.crowdfunding_campaigns(id), title text not null, body text, created_at timestamptz not null default now());
create table public.campaign_expenses(id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.crowdfunding_campaigns(id), amount_paise bigint not null check(amount_paise>0), description text not null, document_path text, created_at timestamptz not null default now());
create table public.projects(id uuid primary key default gen_random_uuid(), title text not null, description text, category text, location text, budget_paise bigint, target_paise bigint, status text not null default 'draft', starts_on date, completed_on date, created_at timestamptz not null default now());
create table public.project_reports(id uuid primary key default gen_random_uuid(), project_id uuid not null references public.projects(id), title text not null, file_path text not null, created_at timestamptz not null default now());
create table public.events(id uuid primary key default gen_random_uuid(), title text not null, description text, location text, starts_at timestamptz, ends_at timestamptz, published boolean not null default false, created_at timestamptz not null default now());
create table public.news(id uuid primary key default gen_random_uuid(), slug text not null unique, title text not null, body text, published boolean not null default false, published_at timestamptz, created_at timestamptz not null default now());
create table public.photo_albums(id uuid primary key default gen_random_uuid(), title text not null, description text, event_id uuid references public.events(id), published boolean not null default false, created_at timestamptz not null default now());
create table public.gallery_images(id uuid primary key default gen_random_uuid(), album_id uuid not null references public.photo_albums(id), file_path text not null, caption text, sort_order int not null default 0);
create table public.videos(id uuid primary key default gen_random_uuid(), title text not null, description text, youtube_url text not null, thumbnail_url text, category text, event_id uuid references public.events(id), published boolean not null default false);
create table public.homepage_slides(id uuid primary key default gen_random_uuid(), title text not null, subtitle text, image_url text, published boolean not null default false, sort_order int not null default 0);
create table public.annual_audit_reports(id uuid primary key default gen_random_uuid(), fiscal_year text not null, title text not null, file_path text not null, published boolean not null default false, created_at timestamptz not null default now());
create table public.awards(id uuid primary key default gen_random_uuid(), title text not null, issuer text, received_on date, description text, file_path text, published boolean not null default false);
create table public.management_team(id uuid primary key default gen_random_uuid(), name text not null, designation text not null, photo_path text, biography text, sort_order int not null default 0, published boolean not null default false);
create table public.complaints(id uuid primary key default gen_random_uuid(), member_id uuid references public.members(id), subject text not null, body text not null, status text not null default 'open', created_at timestamptz not null default now());
