create table public.contact_enquiries(id uuid primary key default gen_random_uuid(), name text not null, mobile text not null, email text, subject text not null, message text not null, status text not null default 'new', created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id), title text not null, body text not null, channel text not null default 'in_app', delivery_status text not null default 'queued', read_at timestamptz, created_at timestamptz not null default now());
create table public.birthdays(id uuid primary key default gen_random_uuid(), member_id uuid not null references public.members(id), banner_path text, created_at timestamptz not null default now());
