-- RLS is on by default for every application table. Public forms may submit only
-- pending membership applications and contact enquiries; management access is role checked.
do $$ declare t text; begin
 for t in select tablename from pg_tables where schemaname='public' and tablename not in ('schema_migrations') loop
  execute format('alter table public.%I enable row level security', t);
 end loop;
end $$;
create policy applications_public_submit on public.membership_applications for insert to anon, authenticated with check(status='pending' and reviewed_by is null and reviewed_at is null);
create policy enquiries_public_submit on public.contact_enquiries for insert to anon, authenticated with check(status='new');
create policy public_slides_read on public.homepage_slides for select to anon, authenticated using(published);
create policy admin_application_read on public.membership_applications for select to authenticated using(public.has_role(array['super_admin','admin']::public.app_role[]));
create policy admin_enquiry_read on public.contact_enquiries for select to authenticated using(public.has_role(array['super_admin','admin']::public.app_role[]));
create policy admin_application_update on public.membership_applications for update to authenticated using(public.has_role(array['super_admin','admin']::public.app_role[])) with check(public.has_role(array['super_admin','admin']::public.app_role[]));
create policy admin_enquiry_update on public.contact_enquiries for update to authenticated using(public.has_role(array['super_admin','admin']::public.app_role[])) with check(public.has_role(array['super_admin','admin']::public.app_role[]));
create policy admin_slides_manage on public.homepage_slides for all to authenticated using(public.has_role(array['super_admin','admin']::public.app_role[])) with check(public.has_role(array['super_admin','admin']::public.app_role[]));
create policy own_profile_read on public.profiles for select to authenticated using(id=auth.uid());
create policy own_profile_update on public.profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy own_roles_read on public.user_roles for select to authenticated using(user_id=auth.uid());
